args.newString:
export default function BlogHeader() {
  return (
    <header>
      <style>
        {`
          @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=Roboto:wght@300;400&display=swap');
        `}
      </style>
      <h1 style={{ fontFamily: 'Playfair Display, serif', fontWeight: 700 }}>My Personal Blog</h1>
      <p style={{ fontFamily: 'Roboto, sans-serif', fontWeight: 300 }}>Thoughts, ideas, and musings</p>
    </header>
  );
}

